package vn.eduassistant.backend.web;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.view.RedirectView;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import java.time.Instant;
import java.util.*;

@RestController
public class CaseController {
    private final AuthService auth;private final CaseService cases;private final UserService users;private final JdbcSupport db;private final AddressService addresses;private final RuleEngineService rules;private final PolicyService policy;private final AuditService audits;private final RedisSupport redis;
    public CaseController(AuthService auth,CaseService cases,UserService users,JdbcSupport db,AddressService addresses,RuleEngineService rules,PolicyService policy,AuditService audits,RedisSupport redis){this.auth=auth;this.cases=cases;this.users=users;this.db=db;this.addresses=addresses;this.rules=rules;this.policy=policy;this.audits=audits;this.redis=redis;}
    @GetMapping("/api/cases/my-cases") public ResponseEntity<?> myCases(HttpServletRequest req){Map<String,Object>u=auth.currentUser(req),identity=UserService.map("userId",u.get("id"),"view","my-cases");Object cached=redis.getJson("cases",identity);if(cached instanceof Map)return ApiResponse.success(200,"Cached cases.",cached);Map<String,Object>f=UserService.map("studentId",u.get("id"));List<Map<String,Object>>list=studentCases(cases.list(f));Map<String,Object>data=UserService.map("cases",list,"total",list.size());redis.setJson("cases",identity,data,30);return ApiResponse.success(200,"Lấy danh sách hồ sơ của sinh viên thành công.",data);}
    @GetMapping("/api/cases") public ResponseEntity<?> list(@RequestParam(defaultValue="ALL")String status,@RequestParam(defaultValue="ALL")String category,@RequestParam(defaultValue="ALL")String department,HttpServletRequest req){Map<String,Object>u=auth.currentUser(req),f=UserService.map("status",status,"category",category,"department",department);if("STUDENT".equals(u.get("role")))f.put("studentId",u.get("id"));Map<String,Object>identity=new LinkedHashMap<String,Object>(f);identity.put("role",u.get("role"));Object cached=redis.getJson("cases",identity);if(cached instanceof Map)return ApiResponse.success(200,"Cached cases.",cached);List<Map<String,Object>>list=cases.list(f);if("STUDENT".equals(u.get("role")))list=studentCases(list);Map<String,Object>data=UserService.map("cases",list,"total",list.size());redis.setJson("cases",identity,data,20);return ApiResponse.success(200,"Lấy danh sách hồ sơ thành công.",data);}
    @GetMapping("/api/cases/{caseId}") public ResponseEntity<?> detail(@PathVariable String caseId,HttpServletRequest req){Map<String,Object>u=auth.currentUser(req),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");if("STUDENT".equals(u.get("role"))&&!Objects.equals(c.get("studentId"),u.get("id"))){audits.log("IDOR_ACCESS_BLOCKED",u,UserService.map("targetCaseOwner",c.get("studentId")),"BLOCKED","Sinh viên cố truy cập hồ sơ của tài khoản khác",caseId);return ApiResponse.failure(403,false,"Bạn không có quyền truy cập hồ sơ của sinh viên khác.",null,"FORBIDDEN");}if("STUDENT".equals(u.get("role")))c=CaseService.studentView(c);Map<String,Object>d=new LinkedHashMap<String,Object>();d.put("case",c);d.putAll(c);return ApiResponse.success(200,"Lấy chi tiết hồ sơ thành công.",d);}
    @PostMapping("/api/cases") public ResponseEntity<?> create(@RequestBody Map<String,Object> req,HttpServletRequest request){Map<String,Object>user=auth.currentUser(request);if(!Arrays.asList("STUDENT","ADMIN").contains(user.get("role")))return ApiResponse.failure(403,false,"Chỉ sinh viên mới được quyền tạo hồ sơ học vụ.",null,"FORBIDDEN");String category=first(Json.str(req.get("category")),"MILITARY_SERVICE_CONFIRMATION");if(!"MILITARY_SERVICE_CONFIRMATION".equals(category))return ApiResponse.failure(400,false,"Hệ thống hiện chỉ tiếp nhận hồ sơ 'MILITARY_SERVICE_CONFIRMATION'. Danh mục '"+category+"' không được hỗ trợ.",null,"INVALID_CATEGORY");
        Map<String,Object>student=users.userById(Json.str(user.get("id")));Map<String,Object>sis=db.one("SELECT * FROM sis_student_records WHERE userid=?",user.get("id"));Map<String,Object>facts=new LinkedHashMap<String,Object>();facts.put("studentId",user.get("id"));String[] keys={"studentCode","fullName","academicStatus","courseStartDate","courseEndDate","currentTermActive","hasCurrentSchedule","registeredPermanentAddress","faculty","recordStatus","sourceType","verificationStatus","verifiedBy","verifiedAt"};for(String key:keys){Object value=sis==null?student.get(key):sis.get(key);if("sourceType".equals(key)&&sis==null)value="LEGACY_ACCOUNT";if("verificationStatus".equals(key)&&sis==null)value="UNVERIFIED";if(sis==null&&"recordStatus".equals(key))value=null;facts.put(key,value);}
        String title=first(Json.str(req.get("title")),"Yêu cầu cấp Giấy xác nhận sinh viên phục vụ tạm hoãn NVQS");String description=first(Json.str(req.get("description")),"");String raw=first(Json.str(req.get("rawAddress")),description);String addrType=first(Json.str(req.get("addressType")),"PERMANENT");Map<String,Object>claim=UserService.map("addressType",addrType,"rawAddress",raw,"declaredAddress",raw,"declaredStructuredAddress",req.get("declaredStructuredAddress"),"requestReason",description.isEmpty()?"Cấp giấy xác nhận sinh viên phục vụ tạm hoãn nghĩa vụ quân sự":description,"notes",first(Json.str(req.get("notes")),""),"studentCode",facts.get("studentCode"),"fullName",facts.get("fullName"));Map<String,Object>address=addresses.normalize(raw,addrType);Map<String,Object>meta=UserService.map("modeUsed",address.get("modeUsed"),"isLive",address.get("isLive"),"isFallback",address.get("isFallback"),"isSynthetic",address.get("isSynthetic"),"fallbackOccurred",address.get("isFallback"),"provider",address.get("provider"),"apiCallPerformed",address.get("apiCallPerformed"),"confidence",address.get("confidence"),"durationMs",address.get("durationMs"));Map<String,Object>ai=UserService.map("normalizedAddress",address.get("normalizedAddress"),"missingFields",address.get("missingFields"),"confidence",address.get("confidence"),"modeUsed",address.get("modeUsed"),"studentClaim",claim,"institutionalFacts",facts,"addressAnalysis",address,"provenance",meta);
        Map<String,Object>caseData=UserService.map("title",title,"category",category,"description",description,"priority",first(Json.str(req.get("priority")),"MEDIUM"),"assignedDepartment",first(Json.str(req.get("assignedDepartment")),"Phòng Quản lý Đào tạo"),"deadline",req.get("deadline"),"evidenceFiles",req.get("evidenceFiles") instanceof List?req.get("evidenceFiles"):Collections.emptyList(),"studentClaim",claim,"institutionalFacts",facts,"authoritativeInstitutionalFacts",facts,"addressAnalysis",address,"aiAddressAnalysis",address,"aiExtraction",ai,"aiMetadata",meta,"addressType",addrType,"rawAddress",raw);
        Map<String,Object> ocr=null;List<?>files=(List<?>)caseData.get("evidenceFiles");if(!files.isEmpty())ocr=Json.object(Json.object(files.get(0)).get("ocrData"));Map<String,Object>verdict=rules.evaluate(caseData,ocr,UserService.map("id",user.get("id"),"studentCode",facts.get("studentCode"),"fullName",facts.get("fullName"),"academicStatus",facts.get("academicStatus"),"courseStartDate",facts.get("courseStartDate"),"courseEndDate",facts.get("courseEndDate"),"currentTermActive",facts.get("currentTermActive"),"hasCurrentSchedule",facts.get("hasCurrentSchedule"),"registeredPermanentAddress",facts.get("registeredPermanentAddress")),meta,null);caseData.put("ruleEngine",verdict);caseData.put("status",verdict.get("status"));if(verdict.get("escalationReason")!=null)caseData.put("escalation",UserService.map("reason",verdict.get("escalationReason"),"explanation",verdict.get("explanation"),"config",verdict.get("escalationConfig"),"ruleMatched",verdict.get("ruleMatched")));
        Map<String,Object> created=cases.create(caseData,user);Map<String,Object> responseCase="STUDENT".equals(user.get("role"))?CaseService.studentView(created):created;Map<String,Object>out=new LinkedHashMap<String,Object>();out.put("case",responseCase);out.putAll(responseCase);return ApiResponse.success(201,"Tạo yêu cầu cấp Giấy xác nhận tạm hoãn NVQS thành công.",out);}
    @PostMapping("/api/cases/{caseId}/supplement") public ResponseEntity<?> supplement(@PathVariable String caseId,@RequestBody Map<String,Object> req,HttpServletRequest request){Map<String,Object>u=auth.currentUser(request),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");if("STUDENT".equals(u.get("role"))&&!Objects.equals(c.get("studentId"),u.get("id")))return ApiResponse.failure(403,false,"Bạn không có quyền bổ sung hồ sơ của sinh viên khác.",null,"FORBIDDEN");List<Object>history=asList(c.get("supplementHistory"));List<?>files=asList(req.get("newEvidenceFiles"));history.add(UserService.map("note",req.get("additionalDescription"),"files",files,"submittedAt",Instant.now().toString()));List<Object>merged=asList(c.get("evidenceFiles"));for(Object f:files)if(!merged.contains(f))merged.add(f);Map<String,Object>updated=cases.updateStatus(caseId,"UNDER_REVIEW",u,first(Json.str(req.get("additionalDescription")),"Sinh viên gửi bổ sung minh chứng"),UserService.map("supplementHistory",history,"evidenceFiles",merged));return caseEnvelope(200,"Bổ sung hồ sơ #"+caseId+" thành công.",updated,Json.str(u.get("role")));}
    @PostMapping("/api/cases/{caseId}/re-route") public ResponseEntity<?> reroute(@PathVariable String caseId,@RequestBody Map<String,Object> req,HttpServletRequest request){Map<String,Object>u=auth.require(request,"REVIEWER","ADMIN"),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");String dept=Json.str(req.get("department"));Map<String,Object>updated=cases.updateStatus(caseId,Json.str(c.get("status")),u,"Cán bộ "+u.get("fullName")+" điều phối hồ sơ sang "+dept,UserService.map("assignedDepartment",dept));return caseEnvelope(200,"Điều phối hồ sơ #"+caseId+" sang "+dept+" thành công.",updated,Json.str(u.get("role")));}
    @PostMapping("/api/cases/{caseId}/evaluate-rules") public ResponseEntity<?> evaluate(@PathVariable String caseId,HttpServletRequest request){auth.require(request,"REVIEWER","ADMIN");Map<String,Object>c=cases.get(caseId),owner=cases.withStudent(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");Map<String,Object>student=owner==null?Collections.<String,Object>emptyMap():Json.object(owner.get("student"));Map<String,Object>facts=Json.object(c.get("institutionalFacts"));Map<String,Object>verdict=rules.evaluate(c,null,student,Json.object(c.get("aiExtraction")),null);return ApiResponse.success(200,"Đánh giá lại quy tắc hồ sơ thành công.",UserService.map("caseId",caseId,"evaluation",verdict));}
    @PostMapping("/api/cases/{caseId}/review") public ResponseEntity<?> review(@PathVariable String caseId,@RequestBody Map<String,Object> req,HttpServletRequest request){Map<String,Object>u=auth.require(request,"REVIEWER","ADMIN"),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");String action=first(Json.str(req.get("action")),Json.str(req.get("decision"))).trim().toUpperCase();Set<String>valid=new HashSet<String>(Arrays.asList("APPROVE","APPROVED","REJECT","REJECTED","REQUEST_INFO","REQUIRE_SUPPLEMENT","REQUIRES_SUPPLEMENT","OVERRIDE","STOP"));if(!valid.contains(action))return ApiResponse.failure(400,false,"Hành động thẩm định không hợp lệ. Chỉ chấp nhận APPROVE, REJECT, REQUEST_INFO, OVERRIDE, STOP.",null,"INVALID_REVIEW_ACTION");boolean override="OVERRIDE".equals(action);String overrideReason=first(Json.str(req.get("overrideReason")),override?Json.str(req.get("reason")):"");if(override&&overrideReason.trim().length()<3)return ApiResponse.failure(400,false,"Bắt buộc phải cung cấp lý do ghi đè (overrideReason) khi thực hiện OVERRIDE.",null,"OVERRIDE_REASON_REQUIRED");String next=override?first(Json.str(req.get("targetStatus")),"APPROVED").toUpperCase():Arrays.asList("APPROVE","APPROVED").contains(action)?"APPROVED":Arrays.asList("REJECT","REJECTED").contains(action)?"REJECTED":Arrays.asList("REQUEST_INFO","REQUIRE_SUPPLEMENT","REQUIRES_SUPPLEMENT").contains(action)?"REQUIRES_SUPPLEMENT":"STOPPED";String invalid=WorkflowGuard.validate(Json.str(c.get("status")),next,Json.str(u.get("role")),override&&"ADMIN".equals(u.get("role")));if(invalid!=null)return ApiResponse.failure(400,false,invalid,null,"INVALID_STATUS_TRANSITION");String label="APPROVED".equals(next)?"CHẤP THUẬN (APPROVED)":"REJECTED".equals(next)?"TỪ CHỐI (REJECTED)":"REQUIRES_SUPPLEMENT".equals(next)?"YÊU CẦU BỔ SUNG HỒ SƠ":"STOPPED".equals(next)?"DỪNG TIẾN TRÌNH XỬ LÝ (STOPPED)":"GHI ĐÈ THẨM ĐỊNH (OVERRIDE -> "+next+")";Map<String,Object> review=UserService.map("action",action,"decision",label,"reason",override?overrideReason:first(Json.str(req.get("reason")),"Thẩm định hồ sơ"),"overrideReason",override?overrideReason:null,"reviewerId",u.get("id"),"reviewerName",u.get("fullName"),"reviewerRole",u.get("role"),"reviewerDepartment",first(Json.str(u.get("department")),Json.str(c.get("assignedDepartment"))),"reviewedAt",Instant.now().toString());if(override)audits.log("HUMAN_OVERRIDE",u,UserService.map("systemRecommendation",Json.object(c.get("ruleEngine")).get("decision"),"humanAction","OVERRIDE","targetStatus",next,"overrideReason",overrideReason),"OVERRIDDEN_TO_"+next,overrideReason,caseId);Map<String,Object>updated=cases.updateStatus(caseId,next,u,override?overrideReason:first(Json.str(req.get("reason")),"Thẩm định viên "+u.get("fullName")+" đã "+label),UserService.map("reviewResult",review,"assignedDepartment",first(Json.str(req.get("assignedDepartment")),Json.str(c.get("assignedDepartment")))));return caseEnvelope(200,"Thẩm định hồ sơ #"+caseId+" thành công ("+next+").",updated,Json.str(u.get("role")));}
    @PostMapping("/api/cases/{caseId}/feedback") public ResponseEntity<?> feedback(@PathVariable String caseId,@RequestBody Map<String,Object> req,HttpServletRequest request){Map<String,Object>u=auth.require(request,"REVIEWER","ADMIN"),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");String type=Json.str(req.get("type")).trim().toUpperCase();String decision=Json.str(Json.object(c.get("ruleEngine")).get("decision"));if(!Arrays.asList("CORRECT","MISSED_ESCALATION","UNNECESSARY_ESCALATION").contains(type))return ApiResponse.failure(400,false,"Loại phản hồi phải là CORRECT, MISSED_ESCALATION hoặc UNNECESSARY_ESCALATION.",null,"INVALID_FEEDBACK_TYPE");if("AUTO_APPROVE".equals(decision)&&"UNNECESSARY_ESCALATION".equals(type)||"ESCALATE_TO_HUMAN".equals(decision)&&"MISSED_ESCALATION".equals(type))return ApiResponse.failure(400,false,"Loại phản hồi không tương thích với đề xuất của hệ thống.",null,"INCOMPATIBLE_FEEDBACK_TYPE");Map<String,Object>result=policy.feedback(caseId,type,first(Json.str(u.get("fullName")),Json.str(u.get("username"))),Json.str(req.get("note")),Json.str(u.get("id")));Map<String,Object> record=Json.object(result.get("record")),entry=UserService.map("type",type,"note",first(Json.str(req.get("note")),""),"reviewerId",u.get("id"),"reviewerName",u.get("fullName"),"reviewerRole",u.get("role"),"oldThreshold",result.get("oldThreshold"),"newThreshold",result.get("newThreshold"),"submittedAt",record.get("createdAt"));List<Object>all=asList(c.get("reviewerFeedback"));all.add(entry);cases.updateStatus(caseId,Json.str(c.get("status")),u,"Thẩm định viên "+u.get("fullName")+" gửi phản hồi feedback: "+type,UserService.map("reviewerFeedback",all));audits.log("REVIEWER_FEEDBACK_SUBMITTED",u,UserService.map("feedbackType",type,"note",req.get("note"),"oldThreshold",result.get("oldThreshold"),"newThreshold",result.get("newThreshold")),"SUCCESS","Phản hồi thẩm định viên "+type,caseId);return ApiResponse.success(200,"Tiếp nhận phản hồi thành công. Ngưỡng tin cậy thích ứng hiện tại: "+result.get("newThreshold")+".",UserService.map("caseId",caseId,"feedback",entry,"threshold",result));}
    @GetMapping("/api/cases/{caseId}/comments") public ResponseEntity<?> comments(@PathVariable String caseId,HttpServletRequest request){Map<String,Object>u=auth.currentUser(request),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");if("STUDENT".equals(u.get("role"))&&!Objects.equals(c.get("studentId"),u.get("id")))return ApiResponse.failure(403,false,"Bạn không có quyền xem bình luận trên hồ sơ của sinh viên khác.",null,"FORBIDDEN");return ApiResponse.success(200,"Lấy danh sách bình luận thành công.",cases.comments(caseId));}
    @PostMapping("/api/cases/{caseId}/comments") public ResponseEntity<?> addComment(@PathVariable String caseId,@RequestBody Map<String,Object>req,HttpServletRequest request){Map<String,Object>u=auth.currentUser(request),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ #"+caseId+".",null,"NOT_FOUND");if("STUDENT".equals(u.get("role"))&&!Objects.equals(c.get("studentId"),u.get("id")))return ApiResponse.failure(403,false,"Bạn không có quyền bình luận trên hồ sơ của sinh viên khác.",null,"FORBIDDEN");String content=Json.str(req.get("content"));if(content.trim().isEmpty())return ApiResponse.failure(400,false,"Nội dung bình luận không được để trống.",null,"EMPTY_COMMENT");return ApiResponse.success(201,"Thêm bình luận thành công.",cases.addComment(caseId,u,content,c));}
    @GetMapping("/api/cases/verify/{caseId}") public ResponseEntity<?> verifyPublic(@PathVariable String caseId){Map<String,Object>v=cases.publicVerification(caseId);return v==null?ApiResponse.failure(404,false,"Không tìm thấy hồ sơ để xác thực.",null,"NOT_FOUND"):ApiResponse.success(200,"Internal workflow record lookup completed.",v);}
    @GetMapping({"/api/reports/export-csv","/api/cases/export/csv"}) public ResponseEntity<byte[]> exportCsv(HttpServletRequest request){auth.require(request,"REVIEWER","ADMIN");StringBuilder csv=new StringBuilder("\uFEFFID,Student,Student Code,Title,Category,Priority,Status,Department,Created At\r\n");for(Map<String,Object>c:cases.list(Collections.<String,Object>emptyMap())){Object[] values={c.get("id"),c.get("studentName"),c.get("studentCode"),c.get("title"),c.get("category"),c.get("priority"),c.get("status"),c.get("assignedDepartment"),c.get("createdAt")};for(int i=0;i<values.length;i++){if(i>0)csv.append(',');csv.append(csv(values[i]));}csv.append("\r\n");}HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.parseMediaType("text/csv; charset=UTF-8"));h.setContentDisposition(ContentDisposition.attachment().filename("EDUASSISTANT_Danh_Sach_Ho_So_"+System.currentTimeMillis()+".csv").build());return new ResponseEntity<byte[]>(csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),h,HttpStatus.OK);}
    @GetMapping({"/api/reports/export-cases-html","/api/cases/export/table"}) public ResponseEntity<String> exportHtml(HttpServletRequest request){auth.require(request,"REVIEWER","ADMIN");StringBuilder html=new StringBuilder("<!doctype html><meta charset='utf-8'><table><thead><tr><th>Mã hồ sơ</th><th>Sinh viên</th><th>Danh mục</th><th>Trạng thái</th><th>Ưu tiên</th></tr></thead><tbody>");for(Map<String,Object>c:cases.list(Collections.<String,Object>emptyMap()))html.append("<tr><td>").append(esc(c.get("id"))).append("</td><td>").append(esc(c.get("studentName"))).append("</td><td>").append(esc(c.get("category"))).append("</td><td>").append(esc(c.get("status"))).append("</td><td>").append(esc(c.get("priority"))).append("</td></tr>");html.append("</tbody></table>");return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body(html.toString());}
    @GetMapping("/api/cases/{caseId}/export-decision") public ResponseEntity<?> exportDecision(@PathVariable String caseId,HttpServletRequest request){Map<String,Object>u=auth.currentUser(request),c=cases.get(caseId);if(c==null)return ApiResponse.failure(404,false,"Không tìm thấy hồ sơ.",null,"NOT_FOUND");if(!"APPROVED".equals(c.get("status")))return ApiResponse.failure(409,false,"Only approved cases have an internal receipt.",null,"CASE_NOT_APPROVED");if("STUDENT".equals(u.get("role"))&&!Objects.equals(c.get("studentId"),u.get("id")))return ApiResponse.failure(403,false,"Bạn không có quyền truy cập quyết định này.",null,"FORBIDDEN");String html="<!doctype html><meta charset='utf-8'><h1>Giấy xác nhận nội bộ</h1><p>Mã hồ sơ: "+esc(c.get("id"))+"</p><p>Sinh viên: "+esc(c.get("studentName"))+"</p><p>MSSV: "+esc(c.get("studentCode"))+"</p><p>Trạng thái: "+esc(c.get("status"))+"</p><p>Chữ ký: "+esc(c.get("digitalSignature"))+"</p>";return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body(html);}
    private ResponseEntity<?> caseEnvelope(int status,String message,Map<String,Object>caseData,String role){Map<String,Object>r="STUDENT".equals(role)?CaseService.studentView(caseData):caseData;Map<String,Object>d=new LinkedHashMap<String,Object>();d.put("case",r);d.putAll(r);return ApiResponse.success(status,message,d);}
    private static List<Map<String,Object>> studentCases(List<Map<String,Object>> items){List<Map<String,Object>>out=new ArrayList<Map<String,Object>>();for(Map<String,Object>c:items)out.add(CaseService.studentView(c));return out;}
    private static List<Object> asList(Object o){if(o instanceof List)return new ArrayList<Object>((List<?>)o);return new ArrayList<Object>();}
    private static String first(String...s){for(String x:s)if(x!=null&&!x.trim().isEmpty())return x;return "";}
    private static String csv(Object value){String s=value==null?"":String.valueOf(value);return "\""+s.replace("\"","\"\"")+"\"";}
    private static String esc(Object value){return String.valueOf(value==null?"":value).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
}
